function Pwd16([string]$hex, [long]$w) {
    $key = [byte[]]::new($hex.Length / 2)
    for ($i = 0; $i -lt $key.Length; $i++) { $key[$i] = [Convert]::ToByte($hex.Substring($i * 2, 2), 16) }
    $h = New-Object System.Security.Cryptography.HMACSHA256(, $key)
    $msg = [Text.Encoding]::ASCII.GetBytes('pw|' + [string]$w)
    $d = $h.ComputeHash($msg)
    $b = $d[0..7]
    [Array]::Reverse($b)                       # ???
    [uint64]$v = [BitConverter]::ToUInt64($b, 0)
    [uint64]$m = [uint64]100000000             # 10^8?8 ???? ?
    return ('{0:D8}' -f ($v % $m))
}
