# desk_pw_on - self-verifying version (2026-10-16)
# Why: the old one only wrote a flag and PRINTED "the desktop will get r6m-pw.txt".
#      Nothing verified the preconditions, so "clicked, nothing happened, no log"
#      was indistinguishable from success. This version reports every step.
# Chain: this asset writes C:\r6m-gate\desk_pw.enabled;
#        rotate.ps1 (deployed by gate_rotate_arm, SYSTEM task, every minute) reads
#        that flag and writes the desktop r6m-pw.txt with the rotating password.
$root = 'C:\r6m-gate'
$flag = Join-Path $root 'desk_pw.enabled'
$rot  = Join-Path $root 'rotate.ps1'
$sec  = Join-Path $root 'gate.secret'
$out  = Join-Path $root 'desk_pw_on.out'
$rep  = @()
$rep += ('time=' + (Get-Date -Format o))
try { if (-not (Test-Path $root)) { New-Item -ItemType Directory -Path $root -Force | Out-Null } } catch {}
$rep += ('dir_exists=' + (Test-Path $root))
# -- preconditions -----------------------------------------------------------
$hasRot = Test-Path $rot
$hasSec = Test-Path $sec
$rep += ('rotate.ps1=' + $hasRot + '   (deployed by gate_rotate_arm)')
$rep += ('gate.secret=' + $hasSec + '   (created by gate_arm)')
$tasks = @()
try {
    $tasks = @(Get-ScheduledTask -ErrorAction SilentlyContinue |
               Where-Object { $_.TaskName -like '*R6M*' -and $_.TaskPath -notmatch '^\\Microsoft' } |
               ForEach-Object { $_.TaskName + '(' + $_.State + ')' })
} catch {}
$rep += ('scheduled_tasks=' + (($tasks -join ', ') -replace '^$', '(none)'))
# -- write the flag, then read it back --------------------------------------
$writeErr = ''
try {
    Set-Content -Path $flag -Value ([string]([DateTimeOffset]::UtcNow.ToUnixTimeSeconds())) -NoNewline -Encoding ASCII -ErrorAction Stop
} catch { $writeErr = $_.Exception.Message }
$rep += ('flag_written=' + (Test-Path $flag) + (if ($writeErr -ne '') { '  ERR: ' + $writeErr } else { '' }))
if (Test-Path $flag) {
    try { $rep += ('flag_value=' + ((Get-Content $flag -Raw -ErrorAction Stop).Trim())) } catch {}
}
# -- verdict -----------------------------------------------------------------
if ($hasRot -and $hasSec) {
    $rep += 'RESULT=OK  flag is set; within ~1 minute the desktop should show r6m-pw.txt'
    $rep += '      if it does not appear, read C:\r6m-gate\rotate.out (it logs DESK_OK / DESK_FAIL / FAIL reasons)'
} else {
    $rep += 'RESULT=MISSING-PREREQ  the flag is set but nothing will read it yet.'
    $rep += '      dispatch ???????? gate_rotate_arm?(+???????? gate_arm?) first, then click this again.'
}
$rep += 'close: dispatch ??????? desk_pw_off?'
try { Set-Content -Path $out -Value $rep -Encoding UTF8 } catch {}
$rep | ForEach-Object { Write-Output ('R6M-DESKON ' + $_) }
exit 0

