# desk_pw_write - computes the rotating password and writes the desktop TXT itself.
# Why: the SYSTEM every-minute task proved fragile (a truncated rotate.ps1 silently
# killed it for hours). An asset always executes, so this does the job directly.
# Template is base64 so this file stays pure ASCII (PS 5.1 mis-parses bare UTF-8).
$root = 'C:\r6m-gate'
$flag = Join-Path $root 'desk_pw.enabled'
$out  = Join-Path $root 'desk_pw_write.out'
$rep  = @()
function L($m) { $script:rep += $m }

try { $sec = ([IO.File]::ReadAllText((Join-Path $root 'gate.secret'))).Trim() } catch { $sec = '' }
if ($sec -eq '') { L 'FAIL: cannot read gate.secret (dispatch gate_arm first)'; [IO.File]::WriteAllText($out, ($rep -join "`r`n"), (New-Object Text.UTF8Encoding($true))); $rep | ForEach-Object { Write-Output ('R6M-DPW ' + $_) }; exit 0 }

$now  = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
$win  = [long][math]::Floor($now / 300)
$left = 300 - ($now % 300)

$key = [byte[]]::new($sec.Length / 2)
for ($i = 0; $i -lt $key.Length; $i++) { $key[$i] = [Convert]::ToByte($sec.Substring($i * 2, 2), 16) }

function Pwd16([byte[]]$k, [long]$w) {
    $h = New-Object System.Security.Cryptography.HMACSHA256(, $k)
    $d = $h.ComputeHash([Text.Encoding]::ASCII.GetBytes('pw|' + [string]$w))
    $b = $d[0..7]; [Array]::Reverse($b)
    [uint64]$v = [BitConverter]::ToUInt64($b, 0)
    return ('{0:D8}' -f ($v % [uint64]100000000))
}
function Totp6([byte[]]$k, [long]$step) {
    $ctr = [BitConverter]::GetBytes([long]$step); [Array]::Reverse($ctr)
    $h = New-Object System.Security.Cryptography.HMACSHA1(, $k)
    $hash = $h.ComputeHash($ctr); $o = $hash[19] -band 0x0f
    $bin = (([int]$hash[$o] -band 0x7f) -shl 24) -bor ([int]$hash[$o+1] -shl 16) -bor ([int]$hash[$o+2] -shl 8) -bor [int]$hash[$o+3]
    return ('{0:D6}' -f ($bin % 1000000))
}
$code5 = Pwd16 $key $win
$code3 = Totp6 $key ([long][math]::Floor($now / 30))
L ('window=' + $win + ' left=' + $left + ' pwd=' + $code5)

# desktop discovery: C:\Users\* with a Desktop dir (no S-1000 assumption)
