        $dk = Join-Path $d.FullName 'Desktop'
        if (Test-Path $dk) { $desk = Join-Path $dk 'r6m-pw.txt'; break }
    }
} catch { }
L ('DESK_PICK=' + $desk)

try { Set-Content -Path $flag -Value ([string]$now) -NoNewline -Encoding ASCII } catch { }
L ('flag=' + (Test-Path $flag))

if ($desk -ne '') {
    $tpl = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
    $txt = $tpl.Replace('__PWD__', $code5).Replace('__LEFT__', [string]$left).Replace('__CODE3__', $code3)
    try {
        [IO.File]::WriteAllText($desk, $txt, (New-Object Text.UTF8Encoding($true)))
        L ('TXT_OK=' + $desk)
    } catch { L ('TXT_FAIL: ' + $_.Exception.Message) }
} else { L 'TXT_SKIPPED: no desktop found' }

try { [IO.File]::WriteAllText($out, ($rep -join "`r`n"), (New-Object Text.UTF8Encoding($true))) } catch { }
$rep | ForEach-Object { Write-Output ('R6M-DPW ' + $_) }
exit 0

